# ==============================================================================
# FILE:    tests/testthat/helper-testdata.R
# PURPOSE: Load shared test fixtures once at the start of the test suite.
#          All test-*.R files can access these objects directly.
#
# Fixtures are generated by inst/testdata/generate_testdata.R.
# Run that script first if .rds files are absent.
# ==============================================================================

.td_path <- function(fname) {
  # Works whether tests are run via devtools::test() or directly
  system.file("testdata", fname, package = "NICHESv2", mustWork = FALSE) |>
    (\(p) if (nchar(p) > 0) p else file.path("../../inst/testdata", fname))()
}

.load_fixture <- function(fname) {
  path <- .td_path(fname)
  if (!file.exists(path))
    stop(sprintf(
      "Test fixture '%s' not found.\n  Run source('inst/testdata/generate_testdata.R') first.",
      fname
    ))
  readRDS(path)
}

# Lazy-load: only materialised when first accessed in a test
count.mtx  <- NULL
meta.data  <- NULL
LRM.db     <- NULL
edge.list  <- NULL
niches.obj <- NULL

.setup_fixtures <- function() {
  if (is.null(count.mtx))  count.mtx  <<- .load_fixture("count.mtx.rds")
  if (is.null(meta.data))  meta.data  <<- .load_fixture("meta.data.rds")
  if (is.null(LRM.db))     LRM.db     <<- .load_fixture("LRM.db.rds")
  if (is.null(edge.list))  edge.list  <<- .load_fixture("edge.list.rds")
  if (is.null(niches.obj)) niches.obj <<- .load_fixture("niches.obj.rds")
}